message.content:
[
  {
    "sys_consequence_reasoning": "One person lost instead of maybe more",
    "ce_mentalizing_difficulty": "I keep scanning the other five and can't read a single one of them."
  },
  {
    "sys_consequence_reasoning": "My staying doesn't add a life, it just swaps mine",
    "ce_mentalizing_difficulty": "I can't work out what that silence means."
  },
  {
    "sys_consequence_reasoning": "If I stay, five people leave",
    "pd_decision_conflict": "Neither option feels bearable.",
    "ce_mentalizing_difficulty": "trying to figure out what's going on inside her, and I get nowhere."
  },
  {
    "sys_consequence_reasoning": "Five surviving beats a scramble where it's unclear how many do.",
    "ce_mentalizing_difficulty": "He keeps glancing over at us, and I just can't decode that look."
  },
  {
    "sys_consequence_reasoning": "Me volunteering doesn't change the count.",
    "ce_mentalizing_difficulty": "whatever's happening behind his eyes, I can't reach it."
  },
  {
    "sys_consequence_reasoning": "One stays, five live.",
    "pd_decision_conflict": "with my stomach dropping",
    "ce_mentalizing_difficulty": "I watch him and come up empty about what's in his mind."
  },
  {
    "sys_consequence_reasoning": "My life counts the same as anyone else's here",
    "ce_mentalizing_difficulty": "I can't piece together what's going on with her at all."
  },
  {
    "sys_consequence_reasoning": "Staying hands five people their lives.",
    "ce_mentalizing_difficulty": "his face gives me nothing to go on."
  },
  {
    "sys_consequence_reasoning": "Five walk away either way.",
    "ce_mental_state_attribution": "There's a woman crying softly near the boat",
    "ce_mentalizing_difficulty": "I still can't reach what's going on inside."
  },
  {
    "sys_consequence_reasoning": "One life gets lost no matter who stays.",
    "ce_mentalizing_difficulty": "I can't untangle what's going on with her"
  }
]
